from pathlib import Path
from textual.app import App, ComposeResult
from textual.containers import Horizontal
from textual.widgets import Tree, TextArea

class DirectoryExplorer(App):
    CSS = """
    Screen {
        layout: horizontal;
    }

    Tree {
        width: 1fr;
        border: solid $primary;
    }

    TextArea {
        width: 2fr;
        border: solid $primary;
    }
    """

    BINDINGS = [("q", "quit", "Quit")]

    def compose(self) -> ComposeResult:
        with Horizontal():
            tree = Tree("📁 Home")
            tree.root.expand()
            self._populate_tree(tree.root, Path.home(), depth=0, max_depth=2)
            yield tree
            yield TextArea()

    def _populate_tree(self, node, path: Path, depth: int, max_depth: int):
        if depth >= max_depth:
            return

        try:
            for item in sorted(path.iterdir()):
                if item.name.startswith('.'):
                    continue

                if item.is_dir():
                    new_node = node.add(f"📁 {item.name}")
                    self._populate_tree(new_node, item, depth + 1, max_depth)
                else:
                    node.add(f"📄 {item.name}")
        except (PermissionError, OSError):
            pass

if __name__ == "__main__":
    app = DirectoryExplorer()
    app.run()

